                                _tn, _ta, _tid = tool_name, args, self.task_id
                                tool_result = await loop.run_in_executor(
                                    _tool_executor,
                                    lambda: handle_function_call(
                                        _tn, _ta, task_id=_tid,
                                        user_task=_user_task,
