def make_object_param(
    name: str,
    description: str = "",
    required: Optional[List[str]] = None,
    properties: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """创建对象参数定义"""
    result = {
        "type": "object",
        "properties": properties or {},
    }
    if description:
        result["description"] = description
    if required:
        result["required"] = required
    return result

